export interface ConnectorConfig {
  /** Shopify shared secret for HMAC-SHA256 verification (used by webhook handler before invoking this connector) */
  shopifySharedSecret: string;
  /** Slack bot token with chat:write scope */
  slackBotToken: string;
  /** Slack channel ID to post messages to (e.g., C12345) */
  slackChannel: string;
  /** Injected fetch implementation for testing; defaults to global fetch */
  fetch?: typeof fetch;
}

export interface ShopifyOrderWebhookPayload {
  id: number;
  name: string;
  email: string;
  total_price: string;
  currency: string;
  line_items: Array<{
    title: string;
    quantity: number;
  }>;
}

export interface HandleResult {
  slackMessageTs: string;
  slackChannel: string;
}

export async function handle(
  payload: ShopifyOrderWebhookPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  // Validate required fields
  const requiredFields: (keyof ShopifyOrderWebhookPayload)[] = [
    'id',
    'name',
    'email',
    'total_price',
    'currency',
    'line_items'
  ];

  for (const field of requiredFields) {
    if (payload[field] === undefined || payload[field] === null) {
      throw new Error(`Missing required field: ${field}`);
    }
  }

  if (!Array.isArray(payload.line_items) || payload.line_items.length === 0) {
    throw new Error('line_items must be a non-empty array');
  }

  // Build Slack blocks per field mapping
  const blocks = [
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: `Order ID: ${payload.id}`
      }
    },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: `Order name / number: ${payload.name}`
      }
    },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: `Customer email: ${payload.email}`
      }
    },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: `Order total: ${payload.total_price} ${payload.currency}`
      }
    },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: `Items: ${payload.line_items.map((item) => `${item.title} x${item.quantity}`).join(', ')}`
      }
    }
  ];

  const fetchImpl = config.fetch ?? fetch;
  const response = await fetchImpl('https://slack.com/api/chat.postMessage', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.slackBotToken}`,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({
      channel: config.slackChannel,
      blocks
    })
  });

  if (!response.ok) {
    throw new Error(
      `Slack API error: ${response.status} ${response.statusText} at https://slack.com/api/chat.postMessage`
    );
  }

  const result = (await response.json()) as { ok: boolean; channel: string; ts: string };

  if (!result.ok) {
    throw new Error(
      `Slack API error: ${response.status} ${response.statusText} at https://slack.com/api/chat.postMessage`
    );
  }

  return {
    slackMessageTs: result.ts,
    slackChannel: result.channel
  };
}

