      shopifySharedSecret: 'test-shared-secret',
      slackBotToken: 'xoxb-test-token',
      slackChannel: 'C12345',
      fetch
    };

    const payload = { ...SOURCE_EXAMPLE, line_items: [] } as unknown as ShopifyOrderWebhookPayload;

    await expect(handle(payload, config)).rejects.toThrow('line_items must be a non-empty array');
